import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String a = scanner.next().toLowerCase();
        String b = scanner.next().toLowerCase();

        int directionA = direction(a);
        int directionB = direction(b);

        int difference = Math.abs(directionA - directionB);
        int turns = Math.min(difference, 4 - difference);

        System.out.println(turns * 90);
    }

    private static int direction(String direction) {
        switch (direction) {
            case "norte": return 0;
            case "leste": return 1;
            case "sul": return 2;
            default: return 3; // oeste
        }
    }
}
